import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "a": [{"converted": True}],
        "b": [{"converted": True}, {"converted": False}, {"converted": None}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (9, 10)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3, 4], days) == expected


@pytest.mark.parametrize("days", [0, 1, 5])
def test_conversions_in_window_empty(days):
    assert conversions_in_window([], days) == 0


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" x1 , 3 , 1 \n", " x2 , -2 , 0 ", " x3 , 4 , \t"]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": -2, "converted": False},
        {"id": "x3", "day": 4, "converted": None},
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", "  \t# comment,not a day", "x#1,3,0"]
    assert parse_session_log(iter(lines)) == [{"id": "x#1", "day": 3, "converted": False}]
    assert parse_session_log(lines[:-1]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,nope,1", "x,1.5,0", "x,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", " \t", "ok,1,1", bad_line])


def test_dedupe_sessions_duplicate_ids_keep_last_input_record():
    events = [
        {"id": "a", "day": 9, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "a", "day": 1, "converted": None},
        {"id": "b", "day": 2, "converted": True},
    ]
    assert dedupe_sessions(events) == [events[2], events[3]]


def test_dedupe_sessions_sorts_by_day_then_id():
    events = [
        {"id": "b", "day": 2, "converted": True},
        {"id": "z", "day": 1, "converted": False},
        {"id": "a", "day": 2, "converted": True},
    ]
    assert dedupe_sessions(events) == [events[1], events[2], events[0]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = parse_session_log([
        "outside,0,1", "a,1,1", "b,1,1", "c,2,0", "d,2,", "e,4,1", "outside2,5,1",
    ])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_campaign_summary_pooled_rate_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "a": parse_session_log(["a,1,1"]),
        "b": parse_session_log(["b,1,0", "c,2,", "d,4,1", "e,5,0", "f,5,0"]),
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]), (20, ["best", "a", "z", "zero"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "empty": [],
        "zero": [{"converted": False}],
        "a": [{"converted": True}, {"converted": False}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 3) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_group():
    groups = {
        "z": [{"converted": False}],
        "b": [],
        "a": [{"converted": True}, {"converted": None}],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.5, "b": None, "z": 0.0}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [
    ([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
    ([1, 1, 0, 1], 2), ([1, -1, 1], 1), ([0, 1, 0, 1, 2, 3], 3),
])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

